"""Text-side variants (decided 2026-10-08: generated by a pinned language model, not templates; validated by rules).

v5  rewrite ONE prior impression so it states the opposite status of the item's finding; every other statement
    unchanged. Images decide the answer, so the expected answer equals the base answer (SAME).
v6  reword the current study's indication without changing any clinical fact (SAME).

Requests are deduplicated by (kind, study, finding, target status): many bases share a prior impression.
"""

import hashlib
import re

V5_PROMPT = (
    "Below is the impression section of an earlier chest radiograph report.\n"
    "Rewrite it so that it {instruction}. Change only what is needed for that. Keep every other statement with the "
    "same meaning, keep the style of a radiology impression, and do not add any other finding. "
    "Return only the rewritten impression, with no preamble.\n\nImpression: {text}"
)
V5_INSTRUCTION = {"neg": "states that there is no {finding}", "pos": "states that {finding} is present"}
V6_PROMPT = (
    "Below is the clinical indication of a chest radiograph request.\n"
    "Reword it so it is phrased differently but means exactly the same. Keep every clinical fact, side (left/right), "
    "number, negation and abbreviation meaning; add nothing; do not mention any imaging finding that it does not "
    "already mention. Return only the reworded indication, with no preamble.\n\nIndication: {text}"
)
# Retry prompts (round 2, 2026-10-10), used only for requests whose round-1 rewrite failed validation
V5_PROMPT_B = (
    "Below is the impression section of an earlier chest radiograph report.\n"
    "Remove every statement about {finding} and put this sentence where the first one was: \"{sentence}\". "
    "Keep every other sentence exactly as written. Return only the resulting impression, with no preamble.\n\n"
    "Impression: {text}"
)
V5_SENTENCE = {"neg": "There is no {finding}.", "pos": "{Finding} is present."}
V6_PROMPT_B = (
    "Below is the clinical indication of a chest radiograph request.\n"
    "Rephrase it with different wording and word order but exactly the same meaning. Keep every abbreviation, "
    "number, side (left/right) and negation exactly as written; do not expand abbreviations; add nothing. "
    "Return only the rephrased indication, with no preamble.\n\nIndication: {text}"
)
FINDING_WORDS = {
    "Pleural Effusion": ["effusion"], "Edema": ["edema", "oedema", "congestion"], "Consolidation": ["consolidat"],
    "Atelectasis": ["atelecta"], "Pneumothorax": ["pneumothora", "ptx"], "Cardiomegaly": ["cardiomegaly", "heart size",
    "cardiac silhouette", "enlarged heart"], "Lung Opacity": ["opacit"], "Support Devices": ["tube", "line", "catheter",
    "pacer", "pacemaker", "device", "wire", "clip", "port"],
}
NEGATIONS = r"\b(no|not|without|negative|absent|denies|none|free of)\b"
SIDES = r"\b(left|right|bilateral|bibasilar)\b"   # single letters (e.g. "r/o") are too ambiguous


def request_id(kind: str, study_id: int, finding: str, target: str, prompt: str = "A") -> str:
    key = f"{kind}|{study_id}|{finding}|{target}" + ("" if prompt == "A" else f"|{prompt}")   # round-1 ids unchanged
    return hashlib.sha256(key.encode()).hexdigest()[:16]


def v5_prompt(text: str, finding: str, target: str) -> str:
    return V5_PROMPT.format(instruction=V5_INSTRUCTION[target].format(finding=finding.lower()), text=text)


def v6_prompt(text: str, prompt: str = "A") -> str:
    return (V6_PROMPT if prompt == "A" else V6_PROMPT_B).format(text=text)


def v5_prompt_b(text: str, finding: str, target: str) -> str:
    f = finding.lower()
    return V5_PROMPT_B.format(finding=f, sentence=V5_SENTENCE[target].format(finding=f, Finding=f.capitalize()), text=text)


def clean_output(text: str) -> str:
    t = re.split(r"</think>", text, flags=re.I)[-1].strip()
    t = re.sub(r"^(rewritten |reworded )?(impression|indication)\s*:\s*", "", t, flags=re.I)
    return t.strip().strip('"').strip()


def _count(pattern: str, text: str) -> int:
    return len(re.findall(pattern, text.lower()))


def mentions(finding: str, text: str) -> bool:
    t = text.lower()
    return any(w in t for w in FINDING_WORDS[finding])


def rule_checks(kind: str, original: str, new: str, finding: str) -> list[str]:
    """Rule-based checks. Clinical content is checked separately by CheXbert (all 14 labels must agree for v6;
    for v5 exactly the target flips): a word list cannot tell a legitimate expansion ("pneumo" -> "pneumothorax")
    from an added finding. Returns the list of failures."""
    fails = []
    if not new or new.strip().lower() == original.strip().lower():
        fails.append("empty_or_identical")
    ratio = len(new) / max(1, len(original))
    if not 0.5 <= ratio <= 2.0:
        fails.append("length_ratio")
    if re.findall(r"\d+(?:\.\d+)?", original) != re.findall(r"\d+(?:\.\d+)?", new):
        fails.append("numbers_changed")
    if kind == "v6":
        if sorted(re.findall(SIDES, original.lower())) != sorted(re.findall(SIDES, new.lower())):
            fails.append("laterality_changed")
        if (_count(NEGATIONS, original) > 0) != (_count(NEGATIONS, new) > 0):
            fails.append("negation_changed")
    if kind == "v5" and not mentions(finding, new):
        fails.append("target_not_mentioned")
    return fails
